-- Aura NBA: Pharma Field Rep "Next Best Action" Console
-- Supabase Schema & Seed Script (Compatible with UUID & Text types, and disables RLS for demo client access)
-- Run this in your Supabase SQL Editor: https://app.supabase.com/project/smcawejdxtkpjynjgzva/sql

-- ============================================================
-- 1. DISABLE RLS OR ALLOW FULL ANON ACCESS
-- ============================================================
ALTER TABLE IF EXISTS public.hcps DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS public.interactions DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS public.recommendations DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS public.outcomes DISABLE ROW LEVEL SECURITY;

-- If tables do not exist yet, create them:
CREATE TABLE IF NOT EXISTS public.hcps (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    specialty TEXT NOT NULL,
    institution TEXT NOT NULL,
    location TEXT NOT NULL,
    segment TEXT NOT NULL,
    therapeutic_area TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS public.interactions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    hcp_id UUID NOT NULL REFERENCES public.hcps(id) ON DELETE CASCADE,
    channel TEXT NOT NULL,
    interaction_type TEXT NOT NULL,
    content_topic TEXT NOT NULL,
    occurred_at TIMESTAMPTZ NOT NULL,
    notes TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS public.recommendations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    hcp_id UUID NOT NULL REFERENCES public.hcps(id) ON DELETE CASCADE,
    recommended_action TEXT NOT NULL,
    recommended_channel TEXT NOT NULL,
    recommended_content TEXT NOT NULL,
    priority TEXT NOT NULL,
    predicted_engagement NUMERIC(5,2) NOT NULL,
    reasons TEXT[] NOT NULL DEFAULT '{}',
    status TEXT NOT NULL DEFAULT 'active',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.outcomes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    recommendation_id UUID NOT NULL REFERENCES public.recommendations(id) ON DELETE CASCADE,
    response TEXT NOT NULL,
    outcome_notes TEXT NOT NULL,
    recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ============================================================
-- 2. SEED DATA (12 HCPs, 57 Interactions, 12 Recommendations, 3 Outcomes)
-- ============================================================

ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    specialty = EXCLUDED.specialty,
    institution = EXCLUDED.institution,
    location = EXCLUDED.location,
    segment = EXCLUDED.segment,
    therapeutic_area = EXCLUDED.therapeutic_area;

ON CONFLICT (id) DO UPDATE SET
    recommended_action = EXCLUDED.recommended_action,
    recommended_channel = EXCLUDED.recommended_channel,
    recommended_content = EXCLUDED.recommended_content,
    priority = EXCLUDED.priority,
    predicted_engagement = EXCLUDED.predicted_engagement,
    reasons = EXCLUDED.reasons,
    status = EXCLUDED.status;

ON CONFLICT (id) DO UPDATE SET
    notes = EXCLUDED.notes;

ON CONFLICT (id) DO UPDATE SET
    response = EXCLUDED.response,
    outcome_notes = EXCLUDED.outcome_notes,
    recorded_at = EXCLUDED.recorded_at;
